{
  "type_map": {},
  "constraints": [
    {
      "id": "R1",
      "category": "math",
      "alternatives": [
        "(df['spkts'] <= 0) | (np.isclose(df['smean'], df['sbytes'] / df['spkts'], rtol=1e-5, atol=1e-8))"
      ],
      "features": ["smean", "sbytes", "spkts"],
      "rationale": "smean is defined as the mean packet size transmitted by the source, so it equals sbytes divided by spkts when spkts > 0."
    },
    {
      "id": "R2",
      "category": "math",
      "alternatives": [
        "(df['dpkts'] <= 0) | (np.isclose(df['dmean'], df['dbytes'] / df['dpkts'], rtol=1e-5, atol=1e-8))"
      ],
      "features": ["dmean", "dbytes", "dpkts"],
      "rationale": "dmean is defined as the mean packet size transmitted by the destination, so it equals dbytes divided by dpkts when dpkts > 0."
    },
    {
      "id": "R3",
      "category": "math",
      "alternatives": [
        "(df['dur'] <= 0) | (np.isclose(df['sload'], (df['sbytes'] * 8) / df['dur'], rtol=1e-5, atol=1e-8))"
      ],
      "features": ["sload", "sbytes", "dur"],
      "rationale": "sload is source bits per second, so it equals sbytes*8 divided by duration in seconds."
    },
    {
      "id": "R4",
      "category": "math",
      "alternatives": [
        "(df['dur'] <= 0) | (np.isclose(df['dload'], (df['dbytes'] * 8) / df['dur'], rtol=1e-5, atol=1e-8))"
      ],
      "features": ["dload", "dbytes", "dur"],
      "rationale": "dload is destination bits per second, so it equals dbytes*8 divided by duration in seconds."
    },
    {
      "id": "R5",
      "category": "math",
      "alternatives": [
        "np.isclose(df['tcprtt'], df['synack'] + df['ackdat'], rtol=1e-5, atol=1e-8)"
      ],
      "features": ["tcprtt", "synack", "ackdat"],
      "rationale": "tcprtt is defined as the sum of synack and ackdat."
    },
    {
      "id": "R6",
      "category": "math",
      "alternatives": [
        "(df['dur'] <= 0) | (np.isclose(df['rate'], (df['spkts'] + df['dpkts']) / df['dur'], rtol=1e-5, atol=1e-8))",
        "(df['dur'] <= 0) | (np.isclose(df['rate'], df['spkts'] / df['dur'], rtol=1e-5, atol=1e-8))",
        "(df['dur'] <= 0) | (np.isclose(df['rate'], (df['sbytes'] + df['dbytes']) / df['dur'], rtol=1e-5, atol=1e-8))"
      ],
      "features": ["rate", "spkts", "dpkts", "sbytes", "dbytes", "dur"],
      "rationale": "rate is undocumented; plausible definitions include total packets per second, source packets per second, or total bytes per second."
    },
    {
      "id": "R7",
      "category": "math",
      "alternatives": [
        "(df['spkts'] <= 0) | (np.isclose(df['sinpkt'], df['dur'] / df['spkts'], rtol=1e-5, atol=1e-8))",
        "(df['spkts'] <= 1) | (np.isclose(df['sinpkt'], df['dur'] / (df['spkts'] - 1), rtol=1e-5, atol=1e-8))",
        "(df['spkts'] <= 0) | (np.isclose(df['sinpkt'], (df['dur'] * 1000) / df['spkts'], rtol=1e-5, atol=1e-8))"
      ],
      "features": ["sinpkt", "dur", "spkts"],
      "rationale": "sinpkt is source interpacket arrival time; plausible definitions include average time per packet (dur/spkts), average gap (dur/(spkts-1)), or in milliseconds (dur*1000/spkts)."
    },
    {
      "id": "R8",
      "category": "math",
      "alternatives": [
        "(df['dpkts'] <= 0) | (np.isclose(df['dinpkt'], df['dur'] / df['dpkts'], rtol=1e-5, atol=1e-8))",
        "(df['dpkts'] <= 1) | (np.isclose(df['dinpkt'], df['dur'] / (df['dpkts'] - 1), rtol=1e-5, atol=1e-8))",
        "(df['dpkts'] <= 0) | (np.isclose(df['dinpkt'], (df['dur'] * 1000) / df['dpkts'], rtol=1e-5, atol=1e-8))"
      ],
      "features": ["dinpkt", "dur", "dpkts"],
      "rationale": "dinpkt is destination interpacket arrival time; plausible definitions include average time per packet (dur/dpkts), average gap (dur/(dpkts-1)), or in milliseconds (dur*1000/dpkts)."
    }
  ]
}
